    def get_select_expr(ext_type: str) -> str:
        """Expression to SELECT back stored data in a stable, output-safe form:
        binary/varbinary/octets are verified via octet_length (raw bytes could
        be hard to compare), utf8 / iso8859_1 varchars -- via char_length +
        octet_length, all other types are selected as is.
        """
        t = ext_type.lower()
        if 'octets' in t or t.startswith('binary') or t.startswith('varbinary'):
            return 'octet_length(f01)'
        if 'utf8' in t or 'iso8859_1' in t:
            return 'char_length(f01), octet_length(f01)'
        return 'f01'

    # Obtain the physical database location.
    # NOTE: we must NOT use 'act.db.db_path' for ALIASED databases! It will return '.' rather than full path+filename.
    # Use only con.info.name for that:
    TEMP_DB_CONF_CONTENT = ''
    with act.db.connect() as con:
        test_db_file = con.info.name
        test_db_path = Path(test_db_file).parent
        TEMP_DB_CONF_CONTENT = f"""
            {CONNECT_TO_ALIAS} = {test_db_file}
            {{
                ExternalFileAccess = Restrict {test_db_path}
            }}
        """
    assert CONNECT_TO_ALIAS in TEMP_DB_CONF_CONTENT and 'ExternalFileAccess' in TEMP_DB_CONF_CONTENT

    # REPLACE databases.conf:
    store_config.replace('databases.conf', TEMP_DB_CONF_CONTENT)

    # Storage of external table will be in the SAME directory as test DB uses.
    # NB: external file is deleted before and after check of every datatype,
    # otherwise rows of previous datatype would be seen by the next one:
    ext_file = test_db_path / 'ext_all_datatypes.dat'
    external_file = str(ext_file).replace("'", "''")

    failed_checks = []

    # NOTE: we make connection to the test DB only once:
    with drv_connect(f'localhost:{CONNECT_TO_ALIAS}', charset = 'utf8',
                     user = act.db.user, password = act.db.password) as con:
        cur = con.cursor()

        for ext_type, valid_values, invalid_values in TYPES_DATA:

            # Remove leftovers from previous iteration / interrupted previous test run:
            ext_file.unlink(missing_ok=True)

            # Trying to create external table for datatype = <ext_type>:
            try:
                con.execute_immediate(f"create table {EXT_TABLE_NAME} external file '{external_file}' (f01 {ext_type})")
                con.commit()
            except DatabaseError as e:
                print(f'Could not create external table for {ext_type=}')
                print(e.__str__())
                print(e.gds_codes)
                # NOTE: no sense to check remaining datatypes if external table can not be created here:
                break

            actual_rows = []
            actual_errors = []

            for v in valid_values:
                try:
                    cur.execute(f'insert into {EXT_TABLE_NAME} values ({v})')
                except DatabaseError as e:
                    actual_errors.append(str(e).strip())

            for v in invalid_values:
                try:
                    cur.execute(f'insert into {EXT_TABLE_NAME} values ({v})')
                except DatabaseError as e:
                    actual_errors.append(str(e).strip())

            # NB: select must be executed in the SAME transaction: inserts are
            # not committed yet, and after rollback() the external file
            # remains empty:
            try:
                cur.execute(f'select {get_select_expr(ext_type)} from {EXT_TABLE_NAME} order by 1')
                for r in cur:
                    actual_rows.append(', '.join(str(x) for x in r))
            except DatabaseError as e:
                actual_errors.append('SELECT FAILED: ' + str(e).strip())

            # Discard inserted data and remove external table, so that next
            # datatype can be checked independently:
            con.rollback()
            con.execute_immediate(f'drop table {EXT_TABLE_NAME}')
            con.commit()
            ext_file.unlink(missing_ok=True)

            exp_stdout = re.sub(r'(?m)^\s+', '', EXPECTED_STDOUT[ext_type]).rstrip()
            exp_stderr = re.sub(r'(?m)^\s+', '', EXPECTED_STDERR[ext_type]).rstrip()
            expected_union = '\n'.join([p for p in (exp_stdout, exp_stderr) if p])
            actual_union = '\n'.join(actual_rows + actual_errors)

            if actual_union != expected_union:
                failed_checks.append(
                    f'mismatch found for {ext_type}:\n'
                    f'Valid literals: {", ".join(valid_values)}\n'
                    f'Invalid literals: {", ".join(invalid_values)}\n'
                    f'expected_union:\n=====\n{expected_union}\n=====\n'
                    f'actual_union:\n=====\n{actual_union}\n=====\n'
                )

    ext_file.unlink(missing_ok=True)

    assert not failed_checks, 'CHECKS FAILED, datatypes and literals that were used:\n' + '\n'.join(failed_checks)
